+    List<String> args,
+    String stdinText,
+  ) async {
+    calls.add((executable, args, stdinText));
+    if (throwOn == calls.length - 1) throw const ProcessException('x', []);
+    return ProcessResult(1, exitCode, null, null);
+  }
