/// The `/provider export` REPL flow (gh-1606): copies the saved Copilot
/// account's full token to the clipboard — no transcript output, no
/// flags, no reveal ceremony. Split from `provider_commands.dart` to keep
/// that file under the 2800-line gate.
part of 'agent_cli.dart';

extension on AgentCli {
  /// The `/provider export` branch: usage + dispatch into the gated flow.
  /// Returns true when the command targeted the export.
  bool _startProviderExportArg(List<String> args) {
    if (args.first != 'export') return false;
    if (args.length > 1) {
      io.writeln('usage: /provider export');
      return true;
    }
    unawaited(_handleProviderExportCommand());
    return true;
  }

  /// Runs the export with the shared flow gate (the picker needs the REPL
  /// answering lines, like the connect flow).
  Future<void> _handleProviderExportCommand() async {
    if (_providerFlowActive) return;
    _providerFlowActive = true;
    try {
      await _runProviderExportCommand();
    } finally {
      _providerFlowActive = false;
      _promptLineBuffer.clear();
    }
  }

  Future<void> _runProviderExportCommand() async {
    final registry = config.customProviders;
    final accounts = [
      for (final entry in registry?.entries ?? const <CustomProviderEntry>[])
        if (entry.apiType == 'copilot') entry,
    ];
    if (accounts.isEmpty) {
      io.writeln(
        'no saved Copilot account — connect one with /provider copilot',
      );
      return;
    }
    final entry = accounts.length == 1
        ? accounts.single
        : await _pickExportCopilotAccount(accounts);
    if (entry == null) {
      io.writeln('Copilot export cancelled');
      return;
    }
    final keyName = entry.keyName;
    final token = [REDACTED:Sensitive Value] == null ? null : config.secureKeys?.read(keyName);
    if (token == null || token.isEmpty) {
      io.writeln(
        'no stored token for ${entry.name} — reconnect with '
        '/provider copilot',
      );
      return;
    }
    final failure = await _copyToClipboard(token);
    if (failure == null) {
      io.writeln('token copied to clipboard');
    } else {
      io.writeln('could not copy the token to the clipboard: $failure');
    }
  }

  /// The multi-account picker of the export flow (the connect flow's
  /// account list minus the "add another account" row). Null = cancelled.
  Future<CustomProviderEntry?> _pickExportCopilotAccount(
    List<CustomProviderEntry> accounts,
  ) async {
    final choice = await _pickOption('Copilot account', [
      for (final entry in accounts)
        (entry.name, entry.name, '${entry.baseUrl} · ${entry.modelId}'),
    ]);
    if (choice == null) return null;
    return config.customProviders?.find(choice);
  }

  /// Copies [text] to the host clipboard. Resolves to null on success, the
  /// named failure reason otherwise (the text itself never surfaces).
  Future<String?> _copyToClipboard(String text) async {
    final injected = config.clipboardWrite;
    if (injected != null) return injected(text);
    final result = await writeClipboardText(text);
    return switch (result) {
      PasteboardWriteOk() => null,
      PasteboardWriteUnavailable(:final reason) => reason,
    };
  }
}

/// Pasteboard text writes for `/provider export` (gh-1606): the saved
/// Copilot token lands on the host clipboard without ever touching the
/// transcript.
///
/// Platform glue only — every platform path funnels through an injected
/// [ClipboardWriteRunner] so tests script the pasteboard instead of
/// touching a real one. The text rides STDIN, never argv: process
/// listings leak arguments, and the payload is a credential.
///
/// - macOS: `pbcopy`
/// - Linux: `xclip -selection clipboard`, falling back to `wl-copy`
///   (Wayland)
/// - Windows: `clip`
library;

import 'dart:io';

import 'paste_image.dart';

export 'paste_image.dart'
    show PasteboardWriteOk, PasteboardWriteResult, PasteboardWriteUnavailable;

/// Runs a process to completion with [stdinText] written to its standard
/// input (injectable `Process` layer).
typedef ClipboardWriteRunner =
    Future<ProcessResult> Function(
      String executable,
      List<String> args,
      String stdinText,
    );

/// The default [ClipboardWriteRunner]: `Process.start`, the text piped to
/// stdin (closed, so the writer sees EOF), streams drained, exit code
/// carried back.
Future<ProcessResult> _runWithStdin(
  String executable,
  List<String> args,
  String stdinText,
) async {
  final process = await Process.start(executable, args);
  process.stdin.write(stdinText);
  await process.stdin.flush();
  await process.stdin.close();
  await process.stderr.drain<void>();
  await process.stdout.drain<void>();
  final exitCode = await process.exitCode;
  return ProcessResult(process.pid, exitCode, null, null);
}

/// The effective platform id (`macos`/`linux`/`windows`): the explicit
/// [platform] pin wins (unit tests — the macOS/Windows paths are
/// unreachable on a Linux CI runner), else the host [Platform]. `null` =
/// no clipboard writer for this platform.
String? _effectivePlatform(String? platform) {
  if (platform != null) return platform;
  if (Platform.isMacOS) return 'macos';
  if (Platform.isLinux) return 'linux';
  if (Platform.isWindows) return 'windows';
  return null;
}

/// Copies [text] to the platform clipboard, trying each platform path in
/// order. Never throws — every failure becomes
/// [PasteboardWriteUnavailable] with the named reason.
Future<PasteboardWriteResult> writeClipboardText(
  String text, {
  ClipboardWriteRunner? runner,
  String? platform,
}) async {
  final run = runner ?? _runWithStdin;
  final paths = switch (_effectivePlatform(platform)) {
    'macos' => const [('pbcopy', <String>[])],
    'linux' => const [
      ('xclip', <String>['-selection', 'clipboard']),
      ('wl-copy', <String>[]),
    ],
    'windows' => const [('clip', <String>[])],
    _ => const <(String, List<String>)>[],
  };
  for (final (executable, args) in paths) {
    try {
      final result = await run(executable, args, text);
      if (result.exitCode == 0) return const PasteboardWriteOk();
    } on Object {
      // Fall through to the next path / the unavailable result.
    }
  }
  return const PasteboardWriteUnavailable(
    'no clipboard writer available (pbcopy/xclip/wl-copy/clip)',
  );
}

