+        expect(runner.calls, hasLength(1));
+        final expected = Platform.isMacOS
+            ? 'pbcopy'
+            : Platform.isWindows
+            ? 'clip'
+            : 'xclip';
+        expect(runner.calls.single.$1, expected);
+        // The credential rides stdin regardless of which arm ran.
+        expect(runner.calls.single.$3, 'gho_TOKEN');
+      },
+    );
+  });
+}
