+/// The default [ClipboardWriteRunner]: `Process.start`, the text piped to
+/// stdin (closed, so the writer sees EOF), streams drained, exit code
+/// carried back.
+Future<ProcessResult> _runWithStdin(
+  String executable,
+  List<String> args,
+  String stdinText,
