+      expect(runner.calls.single.$1, 'pbcopy');
+      expect(runner.calls.single.$2, isEmpty);
+      // Credential rides stdin, never argv (process listings leak args).
+      expect(runner.calls.single.$3, 'github_pat_TOKEN');
+    });
+
