    report: keyPreloadReport,
    referencedKeyNames: referencedSecureKeyNames(saved),
    debug:
        parsed.debugSecrets ||
        isTruthyEnvValue(Platform.environment['FA_DEBUG_KEYS']),
    storeLabel: keyCache.label,
  )) {
    stderr.writeln(line);
  }

