Map<String, String> copilotRequestHeaders({required String copilotToken}) =>
    isFineGrainedGitHubPat(copilotToken)
    ? copilotPatApiHeaders(pat: copilotToken)
    : copilotApiHeaders(copilotToken: copilotToken);

