+/// Runs a process to completion with [stdinText] written to its standard
+/// input (injectable `Process` layer).
+typedef ClipboardWriteRunner =
+    Future<ProcessResult> Function(
+      String executable,
+      List<String> args,
+      String stdinText,
+    );
