+      final runner = _RecordingRunner(0);
+
+      final result = await writeClipboardText(
+        'gho_TOKEN',
+        runner: runner.call,
+        platform: 'windows',
+      );
+
+      expect(result, isA<PasteboardWriteOk>());
+      expect(runner.calls.single.$1, 'clip');
+      expect(runner.calls.single.$3, 'gho_TOKEN');
