+      () async {
+        final runner = _RecordingRunner(0);
+
+        final result = await writeClipboardText(
+          'tok',
+          runner: runner.call,
+          platform: 'templeos',
+        );
+
+        expect(result, isA<PasteboardWriteUnavailable>());
