+    test(
+      'an unknown platform is unavailable without running anything',
+      () async {
+        final runner = _RecordingRunner(0);
+
+        final result = await writeClipboardText(
+          'tok',
+          runner: runner.call,
+          platform: 'templeos',
+        );
