+      expect(result, isA<PasteboardWriteOk>());
+      expect(runner.calls.single.$1, 'xclip');
+      expect(runner.calls.single.$2, ['-selection', 'clipboard']);
+      expect(runner.calls.single.$3, 'gho_TOKEN');
+    });
