    // yaml-disabled one stays null, exactly like the CLI.
    if (_yamlRedactConfig is RedactionConfig && !_yamlRedactConfig!.enabled) {
      return;
    }
    _redactionPipeline ??= RedactionPipeline(
      registeredSecrets: [
