  void _attachRedactor(
    SecretRedactor? redactor, [
    Map<String, String> bootSecrets = const {},
  ]) {
    // Seed for the live re-enable ([AgentServiceAppConfig]).
    if (bootSecrets.isNotEmpty) _bootSecrets = bootSecrets;
